sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    api.setState('ikkatu_hyouji',true);
    var cho = api.state.choiced_ido;
    var riy = api.state.idouriyuu;
    const rows = api.state.meisai_select;
    var test = [];
    var arr = [];
    test.flg = riy;
    test.idouriyuu = cho;

    const keys = Object.keys(rows);

    keys.forEach(function(key) {

        var sysId = rows[key].cells.bikou.metadata.openRecordMetadata.sysId;
        if (arr.indexOf(sysId) === -1) {
        arr.push(sysId);
        }
    });
    test.records = arr.join(',');
    console.log(test);
    api.data.update_test_1.execute(test);

}
